CREATE FUNCTION public.bar_work_shift_status(_club_id uuid,_token uuid DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM public._bar_tip_authorise(_club_id,_token); RETURN jsonb_build_object('shift',(SELECT to_jsonb(w) FROM bar_work_shifts w WHERE w.club_id=_club_id AND w.closed_at IS NULL),'unallocated_tips',coalesce((SELECT sum(t.amount) FROM bar_tips t JOIN bar_work_shifts w ON w.id=t.work_shift_id WHERE t.club_id=_club_id AND w.closed_at IS NOT NULL AND t.status='earned' AND NOT EXISTS(SELECT 1 FROM bar_shift_tip_allocations a WHERE a.tip_id=t.id)),0)); END $$;
REVOKE ALL ON FUNCTION public.bar_work_shift_status(uuid,uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.bar_work_shift_status(uuid,uuid) TO anon,authenticated;
CREATE FUNCTION public.bar_review_shift_tips(_club_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE t record; BEGIN PERFORM _bar_tip_authorise(_club_id,NULL); PERFORM pg_advisory_xact_lock(hashtext('bar_cash_up:'||_club_id)); FOR t IN SELECT bt.id FROM bar_tips bt JOIN bar_work_shifts w ON w.id=bt.work_shift_id WHERE bt.club_id=_club_id AND w.closed_at IS NOT NULL AND bt.status='earned' AND NOT EXISTS(SELECT 1 FROM bar_shift_tip_allocations a WHERE a.tip_id=bt.id) ORDER BY bt.id LOOP PERFORM _bar_allocate_shift_tip(t.id); END LOOP; END $$;
REVOKE ALL ON FUNCTION public.bar_review_shift_tips(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.bar_review_shift_tips(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.bar_staff_attendance_log(_club_id uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM _bar_tip_authorise(_club_id,NULL); RETURN coalesce((SELECT jsonb_agg(jsonb_build_object('id',a.id,'staff_id',a.staff_id,'name',d.label,'kind',w.kind,'start',a.paid_start,'end',a.ended_at,'hours',CASE WHEN a.ended_at IS NOT NULL THEN greatest(extract(epoch FROM(a.ended_at-a.paid_start)),0)/3600 END,'split_tips',w.split_tips,'reason',a.correction_reason,'paid',EXISTS(SELECT 1 FROM bar_payroll_runs r WHERE r.club_id=a.club_id AND r.status='confirmed' AND coalesce(r.attendance_cutoff,r.confirmed_at)>=a.ended_at)) ORDER BY a.paid_start DESC) FROM bar_staff_attendance a JOIN bar_counter_devices d ON d.id=a.staff_id JOIN bar_work_shifts w ON w.id=a.shift_id WHERE a.club_id=_club_id),'[]'::jsonb); END $$;
-- Preserve already-confirmed attendance even when a correction would move it earlier.
DO $ddl$ DECLARE def text; BEGIN SELECT pg_get_functiondef(oid) INTO def FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='bar_correct_staff_attendance'; def:=replace(def,'coalesce(r.attendance_cutoff,r.confirmed_at)>=a.paid_start','coalesce(r.attendance_cutoff,r.confirmed_at)>=least(a.paid_start,_start)'); EXECUTE def; END $ddl$;
-- Allocation serializes with shift closing even when delayed account tips become earned.
DO $ddl$ DECLARE def text; BEGIN SELECT pg_get_functiondef(oid) INTO def FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='_bar_allocate_shift_tip'; def:=replace(def,'SELECT * INTO t FROM bar_tips WHERE id=_tip FOR UPDATE;','SELECT * INTO t FROM bar_tips WHERE id=_tip FOR UPDATE; PERFORM pg_advisory_xact_lock(hashtext(''bar_cash_up:''||t.club_id));'); EXECUTE def; END $ddl$;